let im_u : Finset G.edgeSet :=
  ((G.neighborFinset u).erase v).attach.image
    (fun ⟨w, hw⟩ => ⟨s(u, w), (G.mem_neighborFinset u w).mp (Finset.mem_of_mem_erase hw)⟩)

let im_v : Finset G.edgeSet :=
  ((G.neighborFinset v).erase u).attach.image
    (fun ⟨w, hw⟩ => ⟨s(v, w), (G.mem_neighborFinset v w).mp (Finset.mem_of_mem_erase hw)⟩)
